Task ID: syn_nrf_l1_002_vlan_trunk_reflector
Category: network_routing_forwarding
Difficulty: level_1

Task Instruction:
Write an XDP program that acts as a VLAN trunk reflector. Inspect 802.1Q tagged frames (eth->h_proto == 0x8100). If the 12-bit VLAN ID (VID) is equal to 100, swap the Ethernet source and destination MAC addresses and reflect the frame out the incoming interface with XDP_TX. Pass all other VLAN IDs, untagged traffic, and truncated frames unchanged with XDP_PASS.

Technical Requirements:
- Validate Ethernet and struct vlanhdr bounds
- Check eth->h_proto == bpf_htons(ETH_P_8021Q)
- Extract 12-bit VID (bpf_ntohs(vlan->h_vlan_TCI) & 0x0FFF)
- If VID == 100, swap MAC addresses and return XDP_TX
- Return XDP_PASS for other traffic
- SEC("xdp") and GPL license declaration

Previous Implementation:
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/ipv6.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <linux/icmp.h>
#include <linux/in.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

struct vlanhdr {
    __be16 h_vlan_TCI;
    __be16 h_vlan_encapsulated_proto;
};

SEC("xdp")
int xdp_route_syn_nrf_l1_002_vlan_trunk_reflector(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (eth->h_proto != bpf_htons(ETH_P_8021Q))
        return XDP_PASS;

    struct vlanhdr *vlan = (void *)(eth + 1);
    if ((void *)(vlan + 1) > data_end)
        return XDP_PASS;

    __u16 vid = bpf_ntohs(vlan->h_vlan_TCI) & 0x0FFF;
    if (vid == 100) {
        __be64 tmp = eth->h_dest;
        eth->h_dest = eth->h_source;
        eth->h_source = tmp;
        return XDP_TX;
    }

    return XDP_PASS;
}

char _license[] SEC("license") = "GPL";

