Task ID: syn_nrf_l1_003_gre_tunnel_reflector
Category: network_routing_forwarding
Difficulty: level_1

Task Instruction:
Write an XDP program that acts as a GRE tunnel loopback reflector. Inspect IPv4 GRE packets (ip->protocol == 47). Swap outer Ethernet MAC addresses, swap outer IPv4 source and destination addresses, reset outer IPv4 checksum, and reflect the packet back with XDP_TX. Pass non-GRE traffic unchanged with XDP_PASS.

Technical Requirements:
- Validate Ethernet and outer IPv4 header bounds
- Check ip->protocol == 47 (GRE)
- Swap Ethernet MACs and IPv4 endpoints
- Recalculate IPv4 checksum
- Return XDP_TX for GRE, XDP_PASS for other traffic
- SEC("xdp") and GPL license declaration

Previous Implementation:
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/ipv6.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <linux/icmp.h>
#include <linux/in.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>


SEC("xdp")
int xdp_route_syn_nrf_l1_003_gre_tunnel_reflector(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    if (ip->protocol != IPPROTO_GRE)
        return XDP_PASS;

    unsigned char tmp_mac[ETH_ALEN];
    __builtin_memcpy(tmp_mac, eth->h_dest, ETH_ALEN);
    __builtin_memcpy(eth->h_dest, eth->h_source, ETH_ALEN);
    __builtin_memcpy(eth->h_source, tmp_mac, ETH_ALEN);

    __be16 tmp_csum = ip->check;
    ip->check = 0;
    __u32 csum = ~((__u32)tmp_csum + (ip->saddr ^ ip->daddr));
    ip->check = (__be16)csum;

    return XDP_TX;
}

char _license[] SEC("license") = "GPL";

