Task ID: syn_nrf_l1_004_vxlan_vni_reflector
Category: network_routing_forwarding
Difficulty: level_1

Task Instruction:
Write an XDP program that inspects VXLAN tunnel traffic (UDP port 4789). If the 24-bit VNI equals 100, swap the outer Ethernet MAC addresses, outer IPv4 source/destination addresses, swap UDP source and destination ports, and reflect the frame with XDP_TX. Pass other VNIs and non-VXLAN traffic with XDP_PASS.

Technical Requirements:
- Validate outer Ethernet, IPv4, UDP, and struct vxlanhdr bounds
- Verify UDP destination port is 4789 and VNI == 100
- Swap MACs, IP endpoints, and UDP ports
- Recalculate IPv4 checksum
- Return XDP_TX for VNI 100, XDP_PASS for other traffic
- SEC("xdp") and GPL license declaration

Previous Implementation:
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/ipv6.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <linux/icmp.h>
#include <linux/in.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

SEC("xdp")
int xdp_vxlan_vni_reflector(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    if (ip->protocol != IPPROTO_UDP)
        return XDP_PASS;

    unsigned int ip_hdr_len = ip->ihl * 4;
    if (ip_hdr_len < sizeof(struct iphdr) || (void *)ip + ip_hdr_len > data_end)
        return XDP_PASS;

    struct udphdr *udp = (void *)ip + ip_hdr_len;
    if ((void *)(udp + 1) > data_end)
        return XDP_PASS;

    if (udp->dest != bpf_htons(4789))
        return XDP_PASS;

    struct vxlanhdr *vx = (void *)(udp + 1);
    if ((void *)(vx + 1) > data_end)
        return XDP_PASS;

    __u32 vni = vx->vni;
    if (vni != 100)
        return XDP_PASS;

    unsigned char tmp_mac[ETH_ALEN];
    __builtin_memcpy(tmp_mac, eth->h_dest, ETH_ALEN);
    __builtin_memcpy(eth->h_dest, eth->h_source, ETH_ALEN);
    __builtin_memcpy(eth->h_source, tmp_mac, ETH_ALEN);

    __be16 tmp_port = udp->dest;
    udp->dest = udp->source;
    udp->source = tmp_port;

    // Recalculate IP checksum
    __u32 csum = 0;
    ip->check = 0;
    __u16 *p = (__u16 *)ip;
    #pragma unroll
    for (int i = 0; i < 10; i++)
        csum += p[i];
    while (csum >> 16)
        csum = (csum & 0xFFFF) + (csum >> 16);
    ip->check = ~csum;

    return XDP_TX;
}

char _license[] SEC("license") = "GPL";

