Task ID: syn_nrf_l1_005_gtpu_upf_reflector
Category: network_routing_forwarding
Difficulty: level_1

Task Instruction:
Write an XDP program that inspects GTP-U traffic (UDP destination port 2152). If gtp->teid == 0x12345678, swap outer Ethernet MAC addresses, outer IPv4 source and destination addresses, swap UDP source and destination ports, and reflect the frame with XDP_TX. Pass other TEIDs and non-GTP-U traffic with XDP_PASS.

Technical Requirements:
- Validate outer Ethernet, IPv4, UDP, and struct gtpuhdr bounds
- Verify UDP destination port is 2152 and gtp->teid == bpf_htonl(0x12345678)
- Swap MACs, IP endpoints, and UDP ports
- Recalculate IPv4 checksum
- Return XDP_TX for matching TEID, XDP_PASS for other traffic
- SEC("xdp") and GPL license declaration

Previous Implementation:
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/ipv6.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <linux/icmp.h>
#include <linux/in.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

struct gtpuhdr {
    __be32 teid;
    __be32 seqno;
    __be32 flags;
    __be16 hdr_len;
    __be16 protocol;
    __be32 c_sum;
    char   pad[4];
};

SEC("xdp")
int xdp_route_syn_nrf_l1_005_gtpu_upf_reflector(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    if (ip->protocol != IPPROTO_UDP)
        return XDP_PASS;

    unsigned int ip_hdr_len = ip->ihl * 4;
    if (ip_hdr_len < sizeof(struct iphdr) || (void *)ip + ip_hdr_len > data_end)
        return XDP_PASS;

    struct udphdr *udp = (void *)ip + ip_hdr_len;
    if ((void *)(udp + 1) > data_end)
        return XDP_PASS;

    if (udp->dest != bpf_htons(2152))
        return XDP_PASS;

    struct gtpuhdr *gtp = (void *)(udp + 1);
    if ((void *)(gtp + 1) > data_end)
        return XDP_PASS;

    __u32 teid = bpf_ntohl(gtp->teid);
    if (teid != 0x12345678)
        return XDP_PASS;

    unsigned char tmp_mac[ETH_ALEN];
    __builtin_memcpy(tmp_mac, eth->h_dest, ETH_ALEN);
    __builtin_memcpy(eth->h_dest, eth->h_source, ETH_ALEN);
    __builtin_memcpy(eth->h_source, tmp_mac, ETH_ALEN);

    __be16 tmp_port = udp->dest;
    udp->dest = udp->source;
    udp->source = tmp_port;

    __u32 tmp_ip = ip->daddr;
    ip->daddr = ip->saddr;
    ip->saddr = tmp_ip;

    ip->check = 0;
    __u32 csum = bpf_ntohs(ip->check) + (bpf_ntohl(ip->daddr) - bpf_ntohl(ip->saddr));
    ip->check = bpf_htons((__u16)csum);

    return XDP_TX;
}

char _license[] SEC("license") = "GPL";

