Task ID: syn_nrf_l1_007_proxy_arp_responder
Category: network_routing_forwarding
Difficulty: level_1

Task Instruction:
Write an XDP program that acts as a Proxy ARP responder. Inspect ARP Requests (EtherType 0x0806, opcode 1). If the target IP (ar_tip) is 192.168.100.1, synthesize an ARP Reply: swap Ethernet MACs and set source MAC to 02:00:00:00:00:01, set opcode to 2, set sender MAC to 02:00:00:00:00:01, swap sender and target IP addresses, and return XDP_TX. Pass other ARP requests and protocols with XDP_PASS.

Technical Requirements:
- Validate Ethernet and struct arphdr_eth_ipv4 bounds
- Verify opcode == 1 (ARPOP_REQUEST) and ar_tip == 192.168.100.1
- Synthesize ARP Reply (opcode 2, MAC 02:00:00:00:00:01, swap endpoints)
- Return XDP_TX for target IP, XDP_PASS for other traffic
- SEC("xdp") and GPL license declaration

Previous Implementation:
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/ipv6.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <linux/icmp.h>
#include <linux/in.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

SEC("xdp")
int xdp_syn_nrf_l1_007_proxy_arp_responder(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (eth->h_proto != bpf_htons(ETH_P_ARP))
        return XDP_PASS;

    struct arphdr *arp = (void *)(eth + 1);
    if ((void *)(arp + 1) > data_end)
        return XDP_PASS;

    if (arp->ar_hrd != bpf_htons(ARPHRD_ETHER) ||
        arp->ar_pro != bpf_htons(ETH_P_IP) ||
        arp->ar_hlen != ETH_ALEN ||
        arp->ar_pln != IP_HLEN ||
        arp->ar_op != bpf_htons(ARPOP_REQUEST))
        return XDP_PASS;

    __u8 *tmp_mac = eth->h_dest;
    eth->h_dest = eth->h_source;
    eth->h_source = tmp_mac;

    eth->h_proto = bpf_htons(ETH_P_ARP);

    arp->ar_op = bpf_htons(ARPOP_REPLY);

    __be16 *tmp_ip = &arp->ar_tip;
    arp->ar_tip = arp->ar_sip;
    arp->ar_sip = *tmp_ip;

    unsigned char *src_mac = eth->h_source;
    eth->h_source[0] = 0x02;
    eth->h_source[1] = 0x00;
    eth->h_source[2] = 0x00;
    eth->h_source[3] = 0x00;
    eth->h_source[4] = 0x00;
    eth->h_source[5] = 0x01;

    return XDP_TX;
}

