Task ID: syn_pfs_l2_009_ip_in_ip_nested_loopback_drop
Category: packet_filtering_security
Difficulty: level_2

Task Instruction:
Write an XDP program that inspects IPv4-in-IPv4 tunnel packets (outer IP protocol 4 / IPPROTO_IPIP). Parse the inner IPv4 header (supporting variable outer IHL) and check the inner destination IP address (inner_ip->daddr). If the inner destination address belongs to the loopback network 127.0.0.0/8 (i.e. (ntohl(inner_ip->daddr) & 0xFF000000) == 0x7F000000), drop the packet with XDP_DROP to prevent tunnel-based loopback attacks. Pass valid IP-in-IP packets, non-tunneled traffic, and malformed frames with XDP_PASS.

Technical Requirements:
- Validate Ethernet and outer IPv4 header bounds (accounting for variable outer IHL)
- Verify outer_ip->protocol == 4
- Validate inner struct iphdr bounds
- Check inner_ip->daddr in 127.0.0.0/8 and drop if match
- Pass all other traffic safely
- SEC("xdp") and GPL license declaration

Previous Implementation:
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/ipv6.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <linux/icmp.h>
#include <linux/in.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

SEC("xdp")
int xdp_filter_syn_pfs_l2_009_ip_in_ip_nested_loopback_drop(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    if (ip->protocol != IPPROTO_IPIP)
        return XDP_PASS;

    __u32 ip_hlen = ip->ihl * 4;
    if (ip_hlen < sizeof(*ip) || ip_hlen > 60)
        return XDP_PASS;

    struct iphdr *inner_ip = (void *)ip + ip_hlen;
    if ((void *)(inner_ip + 1) > data_end)
        return XDP_PASS;

    __u32 inner_daddr = ntohl(inner_ip->daddr);
    if ((inner_daddr & 0xFF000000) == 0x7F000000)
        return XDP_DROP;

    return XDP_PASS;
}

