Task ID: syn_pfs_l3_001_token_bucket_policer
Category: packet_filtering_security
Difficulty: level_3

Task Instruction:
Write a stateful XDP token bucket rate limiter in C. Maintain a BPF hash map named 'policer_map' (key __be32 src_ip, value struct bucket_state { __u64 last_time_ns; __u64 tokens; }, max_entries 1024). Configure a rate of 10,000 bytes/second (RATE_BYTES_PER_SEC) and a burst capacity of 5,000 bytes (BURST_CAPACITY). On every IPv4 packet, calculate elapsed time using bpf_ktime_get_ns(), replenish tokens up to BURST_CAPACITY, and deduce packet length. If available tokens are insufficient or packet length exceeds BURST_CAPACITY, drop the packet with XDP_DROP. Otherwise, deduct packet length and return XDP_PASS. Pass non-IPv4 frames unchanged.

Technical Requirements:
- Define struct bucket_state with last_time_ns (__u64) and tokens (__u64)
- Define hash map 'policer_map' with key __be32, value struct bucket_state, max_entries 1024
- Calculate packet wire length: (void *)data_end - (void *)data
- Replenish tokens based on elapsed nanoseconds from bpf_ktime_get_ns()
- Enforce token deduction and drop with XDP_DROP on deficit
- SEC("xdp") and GPL license declaration

Previous Implementation:
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/ipv6.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <linux/icmp.h>
#include <linux/in.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

struct bucket_state {
    __u64 last_time_ns;
    __u64 tokens;
};

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 1024);
    __type(key, __be32);
    __type(value, struct bucket_state);
} policer_map SEC(".maps");

SEC("xdp")
int xdp_token_bucket_policer(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    __be16 proto = ((struct ethhdr *)data)->h_proto;
    if (proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = (void *)(data + sizeof(struct ethhdr));
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    __u64 pkt_len = (__u64)data_end - (__u64)data;
    if (pkt_len > BURST_CAPACITY)
        return XDP_DROP;

    __be32 src_ip = ip->saddr;
    struct bucket_state *state = bpf_map_lookup_elem(&policer_map, &src_ip);
    if (!state) {
        state = bpf_map_lookup_elem(&policer_map, &src_ip);
        if (!state) {
            // Initial allocation
            state = bpf_map_lookup_elem(&policer_map, &src_ip);
            if (state) {
                state->last_time_ns = bpf_ktime_get_ns();
                state->tokens = BURST_CAPACITY;
            }
        }
    }

    if (!state)
        return XDP_PASS;

    __u64 now = bpf_ktime_get_ns();
    __u64 elapsed = now - state->last_time_ns;
    if (elapsed > 0) {
        __u64 tokens_added = (elapsed * RATE_BYTES_PER_SEC) / 1000000000;
        state->tokens += tokens_added;
        if (state->tokens > BURST_CAPACITY)
            state->tokens = BURST_CAPACITY;
        state->last_time_ns = now;
    }

    if (state->tokens < pkt_len) {
        return XDP_DROP;
    }

    state->tokens -= pkt_len;
    return XDP_PASS;
}

