Task ID: syn_pfs_l3_002_bloom_filter_ip_blocklist
Category: packet_filtering_security
Difficulty: level_3

Task Instruction:
Write an XDP program that implements a 3-hash 4096-bit Bloom Filter IP blocklist. Use a BPF array map named 'bloom_filter' (key __u32 word_index, value __u64 bitmap_word, max_entries 64 for 4096 total bits). For each IPv4 packet, compute 3 distinct integer hash values on ntohl(ip->saddr) modulo 4096. Test if the corresponding bits are set in the bitmap words. If all 3 bits are set (indicating positive bloom filter membership), drop the packet with XDP_DROP. Otherwise, return XDP_PASS. Pass non-IPv4 frames safely.

Technical Requirements:
- Define array map 'bloom_filter' with max_entries 64 (64 * 64 = 4096 bits)
- Compute 3 independent hash functions mapping IPv4 address to [0, 4095]
- Lookup bitmap words from bloom_filter map with bounds checking
- Drop packet if and only if all 3 hashed bits are 1 in the bitmap
- Pass non-matching and non-IPv4 packets safely
- SEC("xdp") and GPL license declaration

Previous Implementation:
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/ipv6.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <linux/icmp.h>
#include <linux/in.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

struct {
    __uint(type, BPF_MAP_TYPE_ARRAY);
    __uint(max_entries, 64);
    __type(key, __u32);
    __type(value, __u64);
} bloom_filter_2 SEC(".maps");

static __u64 hash1(__u32 x) {
    return (x * 1111111111) % 4096;
}

static __u64 hash2(__u32 x) {
    return (x * 1111111113) % 4096;
}

static __u64 hash3(__u32 x) {
    return (x * 1111111117) % 4096;
}

SEC("xdp")
int xdp_bloom_filter_syn_pfs_l3_002(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    __u32 saddr = ip->saddr;
    __u64 h1 = hash1(saddr);
    __u64 h2 = hash2(saddr);
    __u64 h3 = hash3(saddr);

    __u32 *bits = (void *)&bloom_filter_2 + (h1 % 64) * sizeof(__u64);
    if (*bits & (1ULL << (h1 % 64)))
        return XDP_DROP;

    bits = (void *)&bloom_filter_2 + (h2 % 64) * sizeof(__u64);
    if (*bits & (1ULL << (h2 % 64)))
        return XDP_DROP;

    bits = (void *)&bloom_filter_2 + (h3 % 64) * sizeof(__u64);
    if (*bits & (1ULL << (h3 % 64)))
        return XDP_DROP;

    return XDP_PASS;
}

