Task Instruction:
Write a stateful XDP port knocking firewall. Maintain client authentication state in a BPF hash map named 'knock_map' (key __be32 src_ip, value struct knock_state { __u32 stage; __u64 last_knock_ns; }, max_entries 1024). Implement a 3-step sequence: UDP port 7000 sets stage 1, UDP port 8000 advances stage 1 -> 2, and UDP port 9000 advances stage 2 -> 3 (authenticated). Each step must occur within 10 seconds of the previous step. For TCP packets targeting destination port 22 (SSH), drop packets with XDP_DROP unless the client is in stage 3 within 10 seconds. Pass all other traffic with XDP_PASS.

Technical Requirements:
- Define struct knock_state with stage (__u32) and last_knock_ns (__u64)
- Define hash map 'knock_map' with key __be32, value struct knock_state, max_entries 1024
- Transition knock state machine: UDP 7000 (stage 1) -> 8000 (stage 2) -> 9000 (stage 3)
- Enforce 10-second timeout window (10,000,000,000 ns) between knocks and for SSH access
- Drop TCP port 22 if unauthenticated (stage != 3 or expired)
- SEC("xdp") and GPL license declaration

Previous Implementation:
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/ipv6.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <linux/icmp.h>
#include <linux/in.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

struct knock_state {
    __u32 stage;
    __u64 last_knock_ns;
};

struct {
    __uint(type, BPF_MAP_TYPE_HASH);
    __uint(max_entries, 1024);
    __type(key, __be32);
    __type(value, struct knock_state);
} knock_map SEC(".maps");

SEC("xdp")
int xdp_knock_auth(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    if (ip->protocol != IPPROTO_UDP)
        return XDP_PASS;

    unsigned int ip_hdr_len = ip->ihl * 4;
    if (ip_hdr_len < sizeof(struct iphdr) || (void *)ip + ip_hdr_len > data_end)
        return XDP_PASS;

    struct udphdr *udp = (void *)ip + ip_hdr_len;
    if ((void *)(udp + 1) > data_end)
        return XDP_PASS;

    __be32 src_ip = ip->saddr;
    struct knock_state *state = bpf_map_lookup_elem(&knock_map, &src_ip);
    if (state) {
        __u64 now = bpf_ktime_get_ns();
        if (now - state->last_knock_ns > 10000000000ULL)
            __sync_fetch_and_add(&state->stage, -3);
    }

    if (udp->dest == bpf_htons(7000)) {
        if (!state) {
            state = bpf_map_lookup_elem(&knock_map, &src_ip);
            if (!state) {
                struct knock_state initial = {.stage = 1, .last_knock_ns = bpf_ktime_get_ns()};
                bpf_map_update_elem(&knock_map, &src_ip, &initial, BPF_ANY);
                return XDP_PASS;
            }
        } else if (state->stage == 0) {
            state->stage = 1;
            state->last_knock_ns = bpf_ktime_get_ns();
            return XDP_PASS;
        }
        return XDP_PASS;
    }

    if (udp->dest == bpf_htons(8000)) {
        if (state && state->stage == 1) {
            state->stage = 2;
            state->last_knock_ns = bpf_ktime_get_ns();
            return XDP_PASS;
        }
        return XDP_PASS;
    }

    if (udp->dest == bpf_htons(9000)) {
        if (state && state->stage == 2) {
            state->stage = 3;
            state->last_knock_ns = bpf_ktime_get_ns();
            return XDP_PASS;
        }
        return XDP_PASS;
    }

    if (ip->protocol == IPPROTO_TCP) {
        struct tcphdr *tcp = (void *)udp + sizeof(struct udphdr);
        if ((void *)(tcp + 1) > data_end)
            return XDP_PASS;

        if (tcp->dest == bpf_htons(22)) {
            if (state && state->stage == 3) {
                __u64 now = bpf_ktime_get_ns();
                if (now - state->last_knock_ns <= 10000000000ULL)
                    return XDP_PASS;
            }
            return XDP_DROP;
        }
    }

    return XDP_PASS;
}

