SEC("xdp")
int xdp_telemetry_syn_pit_l2_002_geneve_opt_class_histogram(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    if (ip->protocol != IPPROTO_UDP)
        return XDP_PASS;

    unsigned int ip_hdr_len = ip->ihl * 4;
    if (ip_hdr_len < sizeof(struct iphdr) || (void *)ip + ip_hdr_len > data_end)
        return XDP_PASS;

    struct udphdr *udp = (void *)ip + ip_hdr_len;
    if ((void *)(udp + 1) > data_end)
        return XDP_PASS;

    if (udp->dest != bpf_htons(6081))
        return XDP_PASS;

    unsigned int geneve_hdr_len = sizeof(struct geneve_hdr);
    if ((void *)udp + geneve_hdr_len > data_end)
        return XDP_PASS;

    struct geneve_hdr *geneve = (void *)udp;
    if (geneve->flags & bpf_htons(0x8000))
        return XDP_PASS;

    __u32 key = 3; // Other
    __u64 *cnt = bpf_map_lookup_elem(&geneve_class_map, &key);
    if (cnt)
        *cnt += 1;

    // Check TLV options
    unsigned char *opt = (void *)geneve + geneve_hdr_len;
    while (opt + 2 <= data_end) {
        __u16 len = bpf_ntohs(geneve->options + (opt - (void *)geneve));
        if (len < 2 || (void *)opt + len > data_end)
            break;
        if (opt[1] == 0x01) { // Option Class
            __u8 class = opt[2];
            if (class == 0x01) {
                key = 0;
            } else if (class == 0x02) {
                key = 1;
            } else if (class == 0x03) {
                key = 2;
            }
            cnt = bpf_map_lookup_elem(&geneve_class_map, &key);
            if (cnt)
                *cnt += 1;
        }
        opt += len;
    }

    return XDP_PASS;
}

