Write an XDP program that inspects GENEVE tunnel packets (UDP destination port 6081). If gen->opt_len > 0, set gen->opt_len = 0 to strip options from the active header definition. Return XDP_PASS.

Technical Requirements:
- Validate Ethernet, IPv4, UDP, and struct genevehdr bounds
- Check UDP destination port 6081
- Set gen->opt_len = 0
- Always return XDP_PASS
- SEC("xdp") and GPL license declaration

Previous Implementation:
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/ipv6.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <linux/icmp.h>
#include <linux/in.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

SEC("xdp")
int xdp_transform_syn_ptr_l2_006_geneve_opt_strip(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    if (ip->protocol != IPPROTO_UDP)
        return XDP_PASS;

    unsigned int ip_hdr_len = ip->ihl * 4;
    if (ip_hdr_len < sizeof(struct iphdr) || (void *)ip + ip_hdr_len > data_end)
        return XDP_PASS;

    struct udphdr *udp = (void *)ip + ip_hdr_len;
    if ((void *)(udp + 1) > data_end)
        return XDP_PASS;

    if (udp->dest == bpf_htons(6081)) {
        struct genevehdr *gen = (void *)(udp + 1);
        if ((void *)(gen + 1) > data_end)
            return XDP_PASS;

        if (gen->opt_len > 0)
            gen->opt_len = 0;
    }

    return XDP_PASS;
}

