Write an XDP program that strips IPv4 options from IPv4 packets where ihl == 6 (24-byte header containing 4 bytes of options). Use bpf_xdp_adjust_head(ctx, 4) to pop 4 bytes, restore Ethernet MACs, set ip->ihl = 5, update ip->tot_len, recompute the IPv4 header checksum, and return XDP_PASS. Pass packets with ihl == 5 unchanged.

Technical Requirements:
- Validate Ethernet and struct iphdr bounds
- Verify ip->ihl == 6
- Pop 4 option bytes using bpf_xdp_adjust_head(ctx, 4)
- Restore MACs, set ip->ihl = 5, and update IPv4 checksum
- Always return XDP_PASS
- SEC("xdp") and GPL license declaration

Previous Implementation:
#include <linux/bpf.h>
#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/ipv6.h>
#include <linux/tcp.h>
#include <linux/udp.h>
#include <linux/icmp.h>
#include <linux/in.h>
#include <bpf/bpf_helpers.h>
#include <bpf/bpf_endian.h>

SEC("xdp")
int xdp_transform_syn_ptr_l2_007_ipv4_options_strip(struct xdp_md *ctx) {
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    struct ethhdr *eth = data;
    if ((void *)(eth + 1) > data_end)
        return XDP_PASS;

    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    if (ip->protocol != IPPROTO_TCP)
        return XDP_PASS;

    if (ip->ihl != 6)
        return XDP_PASS;

    unsigned char tmp_mac[ETH_ALEN];
    __builtin_memcpy(tmp_mac, eth->h_dest, ETH_ALEN);
    __builtin_memcpy(eth->h_dest, eth->h_source, ETH_ALEN);
    __builtin_memcpy(eth->h_source, tmp_mac, ETH_ALEN);

    __u32 old_len = ip->tot_len;
    int res = bpf_xdp_adjust_head(ctx, 4);
    if (res < 0)
        return XDP_PASS;

    ip = (void *)(eth + 1);
    if ((void *)(ip + 1) > data_end)
        return XDP_PASS;

    ip->ihl = 5;
    ip->tot_len = bpf_htons(bpf_ntohs(old_len) - 4);

    __u32 csum = 0;
    __u16 *p = (__u16 *)ip;
    #pragma unroll
    for (int i = 0; i < 10; i++)
        csum += p[i];
    while (csum >> 16)
        csum = (csum & 0xFFFF) + (csum >> 16);
    ip->check = ~csum + bpf_htons(0xFFFF);

    return XDP_PASS;
}

